const input = $('Webhook Inbound WhatsApp').first().json.body;
const text = (input.text || '').toLowerCase().trim();
const history = $input.first().json.history || [];
const hasHistory = history.length > 0;

function isRealEstateIntent(t) {
  const explicitWords = [
    'elasa', 'еласа', 'апартамент', 'apartament', 'apartment', 'вила', 'villa', 'студио', 'studio',
    'каликратия', 'kallikratia', 'халкидики', 'halkidiki', 'гърция', 'greece',
    'нощувк', 'нощувки', 'резервац', 'booking', 'airbnb',
    'почивка', 'почивката', 'на море', 'на плаж', 'плажа'
  ];
  if (explicitWords.some(w => t.includes(w))) return true;

  const intentRoots = ['свобод', 'цена', 'цени', 'наем', 'зает', 'струва'];
  const contextRoots = ['юли', 'август', 'септември', 'юни', 'май', 'лято', 'нощув', 'дат', 'гост', 'човек', 'души', 'двойка', 'семейство', 'beach', 'july', 'august'];
  return intentRoots.some(r => t.includes(r)) && contextRoots.some(r => t.includes(r));
}

const matchesKeyword = isRealEstateIntent(text);
const shouldRespond = matchesKeyword || hasHistory;

let formattedHistory = 'No previous messages.';
if (hasHistory) {
  formattedHistory = history.map(m => `${m.role === 'user' ? 'Client' : 'Concierge'}: ${m.content}`).join('\n');
}

return [{
  json: {
    shouldRespond,
    phone: input.phone,
    pushName: input.pushName || 'Client',
    text: input.text,
    hasHistory,
    historyCount: history.length,
    formattedHistory
  }
}];
